import hashlib, re
from datetime import datetime, timezone

def now(): return datetime.now(timezone.utc).isoformat()
def digest(value): return hashlib.sha256(value.encode()).hexdigest()
def classify(text, path, kind):
    match = re.search(r'(?im)^\s*(?:[-*]\s*)?(?:\*\*)?status(?:\*\*)?\s*[:|]\s*(?:\*\*)?(accepted|proposed|draft|superseded|deprecated|withdrawn)', text)
    status = match.group(1).lower() if match else 'unknown'
    return {'decision_status':status,'status_evidence':match.group(0) if match else None,
            'role':'reported-concern' if kind != 'file' else ('decision' if '/adr/' in '/'+path else 'implementation-requirement' if 'conformance' in path else 'source-document'),
            'unresolved_questions':[line for line in text.splitlines() if re.search(r'(?i)open question|unresolved|to be determined|historical.*key|TODO',line)],
            'specifications':[{'identity':m.group(0),'cited_version':m.group(1),'upstream_version':None,'evidence':m.group(0)} for m in re.finditer(r'(?:ETSI\s+(?:TS|EN)\s+[\d ]+|OpenID[^\n]{0,45}|ARF)\s+[vV]?(\d+\.\d+(?:\.\d+)?)',text)],
            'topics':[term for term in ('AuthZEN','EBWV','OID4VP','OID4VCI','trust','rulebook') if term.lower() in text.lower()]}

def record(identity, revision, url, text, repo, kind='file', path='', lifecycle='unknown', updated=None, permissions='metadata-only'):
    return dict(id=identity,revision=revision,url=url,locator=path or url,repository=repo,kind=kind,title=path or identity,
        text=text,content_hash=digest(text),visibility='public',reuse_permissions=permissions,updated_at=updated,retrieved_at=now(),
        lifecycle=lifecycle,aliases=[],actors=[],credential_types=[],ebwv_identifiers=re.findall(r'https?://[^\s<>]*ebwv[^\s<>]*',text),
        provenance={'extractor':'deterministic-v1','annotation_model':None,'prompt_version':None},**classify(text,path,kind))

def validate(records):
    for r in records:
        assert r['visibility']=='public' and r['url'].startswith('https://')
        assert r['content_hash']==digest(r['text'])
        assert r['decision_status']=='unknown' or r['status_evidence'] in r['text']
        for s in r['specifications']: assert s['evidence'] in r['text']

import os
from sentence_transformers import SentenceTransformer
class Embeddings:
    def __init__(self):
        self.name=os.getenv('EMBEDDING_MODEL','sentence-transformers/all-MiniLM-L6-v2')
        self.revision=os.environ['EMBEDDING_REVISION']
        self.model=SentenceTransformer(self.name,revision=self.revision,device='cpu',trust_remote_code=False)
        self.dimension=self.model.get_sentence_embedding_dimension()
    def encode(self,texts): return self.model.encode(texts,normalize_embeddings=True).tolist()
    @property
    def metadata(self): return {'model':self.name,'revision':self.revision,'dimension':self.dimension}

CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS snapshots(id text PRIMARY KEY, manifest jsonb NOT NULL, published_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS publication(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), snapshot text REFERENCES snapshots);
CREATE TABLE IF NOT EXISTS records(snapshot text REFERENCES snapshots, id text, revision text, data jsonb NOT NULL, content text NOT NULL, embedding vector(384) NOT NULL, search tsvector GENERATED ALWAYS AS (to_tsvector('english', content)) STORED, PRIMARY KEY(snapshot,id));
CREATE INDEX IF NOT EXISTS records_fts ON records USING gin(search);
CREATE INDEX IF NOT EXISTS records_vector ON records USING hnsw(embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS relations(snapshot text, source text, target text, kind text, evidence jsonb, confirmed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS revoked(id text PRIMARY KEY, reason text NOT NULL);
-- Roles are created with passwords by the operator, never committed here.
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO gateway_reader, gateway_ingest;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO gateway_reader;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO gateway_ingest;
ALTER ROLE gateway_reader SET default_transaction_read_only=on;
ALTER ROLE gateway_reader SET statement_timeout='5s';
ALTER ROLE gateway_ingest SET statement_timeout='120s';

import json, os
import psycopg
from psycopg.rows import dict_row
from psycopg.types.json import Jsonb
from .model import digest,now,validate
class Store:
    def __init__(self,dsn,embed): self.dsn,self.embed=dsn,embed
    def connect(self): return psycopg.connect(self.dsn,row_factory=dict_row)
    def manifest(self,snapshot=None):
        with self.connect() as c:
            row=c.execute('SELECT manifest FROM snapshots WHERE id=COALESCE(%s,(SELECT snapshot FROM publication))',(snapshot,)).fetchone()
        if not row: raise LookupError('Snapshot unavailable')
        return row['manifest']
    def publish(self,records,coverage):
        validate(records)
        sid=digest(json.dumps([(r['id'],r['revision'],r['content_hash']) for r in sorted(records,key=lambda r:r['id'])])+json.dumps(coverage,sort_keys=True)+json.dumps(self.embed.metadata))[:24]
        vectors=self.embed.encode([r['title']+'\n'+r['text'] for r in records])
        manifest={'snapshot':sid,'schema_version':1,'published_at':now(),'coverage':coverage,'embeddings':self.embed.metadata,'records':len(records)}
        with self.connect() as c:
            if c.execute('SELECT 1 FROM snapshots WHERE id=%s',(sid,)).fetchone(): return sid
            c.execute('INSERT INTO snapshots(id,manifest) VALUES(%s,%s)',(sid,Jsonb(manifest)))
            for r,v in zip(records,vectors):
                c.execute('INSERT INTO records(snapshot,id,revision,data,content,embedding) VALUES(%s,%s,%s,%s,%s,%s::vector)',(sid,r['id'],r['revision'],Jsonb(r),r['title']+'\n'+r['text'],str(v)))
                for target in __import__('re').findall(r'https://[^\s<>\)\]]+',r['text']):
                    c.execute('INSERT INTO relations VALUES(%s,%s,%s,%s,%s,true)',(sid,r['id'],target,'references',Jsonb({'url':r['url'],'revision':r['revision'],'span':target})))
            c.execute('INSERT INTO publication VALUES(true,%s) ON CONFLICT(singleton) DO UPDATE SET snapshot=EXCLUDED.snapshot',(sid,))
        return sid
    def search(self,q,snapshot=None,status=None,version=None,scope=None,offset=0,limit=20):
        if not q.strip() or len(q)>1000 or not 1<=limit<=100 or not 0<=offset<=10000: raise ValueError('Invalid query or pagination')
        manifest=self.manifest(snapshot); sid=manifest['snapshot']
        if manifest['embeddings']!=self.embed.metadata: raise ValueError('Embedding model mismatch')
        v=str(self.embed.encode([q])[0])
        sql='''WITH candidates AS (SELECT id,data,embedding <=> %s::vector AS distance,
          ts_rank_cd(search,websearch_to_tsquery('english',%s)) AS lexical,
          CASE WHEN content ILIKE %s THEN 1 ELSE 0 END AS exact FROM records
          WHERE snapshot=%s AND NOT EXISTS(SELECT 1 FROM revoked WHERE revoked.id=records.id)
          AND (%s::text IS NULL OR data->>'decision_status'=%s)
          AND (%s::text IS NULL OR data->>'repository'=%s)
          AND (%s::text IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(data->'specifications') s WHERE s->>'cited_version'=%s)))
          SELECT data,distance,lexical, (1-distance)+least(lexical,1)+exact AS score,count(*) OVER() AS total
          FROM candidates ORDER BY score DESC,id LIMIT %s OFFSET %s'''
        with self.connect() as c: rows=c.execute(sql,(v,q,'%'+q+'%',sid,status,status,scope,scope,version,version,limit,offset)).fetchall()
        return {'snapshot':sid,'published_at':manifest['published_at'],'offset':offset,'limit':limit,'total':rows[0]['total'] if rows else 0,'results':[dict(source=self.permitted(r['data']),score=r['score'],vector_distance=r['distance'],lexical_score=r['lexical']) for r in rows]}
    @staticmethod
    def permitted(data):
        data=dict(data)
        if data['reuse_permissions']!='full-text': data.pop('text',None); data['content_available']=False
        return data
    def source(self,id,snapshot=None):
        sid=self.manifest(snapshot)['snapshot']
        with self.connect() as c: row=c.execute('SELECT data FROM records WHERE snapshot=%s AND id=%s AND NOT EXISTS(SELECT 1 FROM revoked WHERE revoked.id=records.id)',(sid,id)).fetchone()
        if not row: raise LookupError(id)
        return {'snapshot':sid,'source':self.permitted(row['data'])}
    def related(self,id=None,topic=None,snapshot=None,specs=False):
        sid=self.manifest(snapshot)['snapshot']
        with self.connect() as c:
            rows=c.execute('SELECT * FROM relations WHERE snapshot=%s AND (%s::text IS NULL OR source=%s) AND NOT EXISTS(SELECT 1 FROM revoked WHERE revoked.id=source OR revoked.id=target)',(sid,id,id)).fetchall()
        if topic: rows=[r for r in rows if topic.lower() in json.dumps(r).lower()]
        if specs: rows=[r for r in rows if any(h in r['target'] for h in ['etsi.org','openid.net','rfc-editor.org','eur-lex.europa.eu'])]
        return {'snapshot':sid,'relations':rows}
    def history(self,id):
        with self.connect() as c: rows=c.execute('SELECT snapshot,revision,data FROM records WHERE id=%s AND NOT EXISTS(SELECT 1 FROM revoked WHERE revoked.id=records.id) ORDER BY snapshot',(id,)).fetchall()
        return {'history':[dict(snapshot=r['snapshot'],revision=r['revision'],source=self.permitted(r['data'])) for r in rows]}
    def changes(self,before,after=None):
        sid=self.manifest(after)['snapshot']; self.manifest(before)
        with self.connect() as c:
            rows=c.execute('''SELECT COALESCE(a.id,b.id) id, a.revision before, b.revision after FROM
            (SELECT * FROM records WHERE snapshot=%s) a FULL JOIN
            (SELECT * FROM records WHERE snapshot=%s) b ON a.id=b.id
            WHERE a.revision IS DISTINCT FROM b.revision AND NOT EXISTS(SELECT 1 FROM revoked WHERE revoked.id=COALESCE(a.id,b.id))''',(before,sid)).fetchall()
        return {'before':before,'snapshot':sid,'changes':rows}

"""Public GET-only adapter; full pagination and explicit per-source coverage."""
import base64,json,os,re
from pathlib import Path
from urllib.parse import urlparse
import httpx
from .model import record,digest,now
class GitHub:
    def __init__(self,client=None): self.client=client or httpx.Client(timeout=30,headers={'Accept':'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'})
    def get(self,url):
        if not url.startswith('https://api.github.com/'): raise ValueError('Unapproved fetch')
        r=self.client.get(url);r.raise_for_status();return r
    def pages(self,url):
        while url:
            r=self.get(url); yield from r.json();url=r.links.get('next',{}).get('url')
    def repo(self,name):
        base='https://api.github.com/repos/'+name; meta=self.get(base).json()
        if meta['private']: raise PermissionError('Private source')
        commit=self.get(base+'/commits/'+meta['default_branch']).json()['sha']
        tree=self.get(base+'/git/trees/'+commit+'?recursive=1').json()
        if tree.get('truncated'): raise RuntimeError('Truncated tree: refusing incomplete capture')
        permission='full-text' if (meta.get('license') or {}).get('spdx_id') in ['MIT','Apache-2.0','CC-BY-4.0','CC0-1.0','BSD-3-Clause','GPL-3.0'] else 'metadata-only'
        rows=[];counts={'tree_entries':len(tree['tree']),'binary_or_unsupported':0,'files':0,'issues':0,'pulls':0,'comments':0,'reviews':0,'review_comments':0,'releases':0}
        for entry in tree['tree']:
            path=entry['path']
            if entry['type']!='blob':continue
            if not path.endswith(('.md','.txt','.json','.jsonld','.yaml','.yml','.ttl','.xml','.csv','.rst','.adoc')): counts['binary_or_unsupported']+=1;continue
            blob=self.get(base+'/git/blobs/'+entry['sha']).json()
            if blob.get('encoding')!='base64':raise RuntimeError('Unsupported blob encoding')
            text=base64.b64decode(blob['content']).decode('utf-8',errors='replace')
            # Stable GitHub repository numeric identity plus path; blob SHA is immutable revision.
            rows.append(record(f"github:{meta['id']}:file:{path}",entry['sha'],f'https://github.com/{name}/blob/{commit}/{path}',text,name,path=path,updated=None,permissions=permission));counts['files']+=1
        for issue in self.pages(base+'/issues?state=all&per_page=100'):
            kind='pull' if 'pull_request' in issue else 'issue';counts[kind+'s']+=1
            rows.append(record('github:'+str(issue['node_id']),digest(json.dumps(issue,sort_keys=True)),issue['html_url'],issue['title']+'\n'+(issue['body'] or ''),name,kind,lifecycle=issue['state'],updated=issue['updated_at'],permissions=permission))
            for comment in self.pages(issue['comments_url']+'?per_page=100'):
                rows.append(record('github:'+comment['node_id'],digest(json.dumps(comment,sort_keys=True)),comment['html_url'],comment['body'],name,'comment',updated=comment['updated_at'],permissions=permission));counts['comments']+=1
            if kind=='pull':
                for endpoint,ck in [('reviews','reviews'),('comments','review_comments')]:
                    for contribution in self.pages(base+'/pulls/'+str(issue['number'])+'/'+endpoint+'?per_page=100'):
                        text=contribution.get('body') or ''; url=contribution.get('html_url') or issue['html_url']
                        rows.append(record('github:'+contribution['node_id'],digest(json.dumps(contribution,sort_keys=True)),url,text,name,ck,lifecycle=contribution.get('state','unknown'),updated=contribution.get('updated_at') or contribution.get('submitted_at'),permissions=permission));counts[ck]+=1
        for release in self.pages(base+'/releases?per_page=100'):
            rows.append(record('github:'+release['node_id'],digest(json.dumps(release,sort_keys=True)),release['html_url'],release['tag_name']+'\n'+(release['body'] or ''),name,'release',updated=release['published_at'],permissions=permission));counts['releases']+=1
        coverage={'repository':name,'state':'complete-for-supported-types','captured_at':now(),'commit':commit,'counts':counts,'types':{'files':'complete textual default-branch files','issues':'all states, paginated','pulls':'all states via issues','comments':'paginated','reviews':'paginated','review_comments':'paginated','releases':'paginated','discussions':'not captured: GraphQL read credential required','wiki':'not captured: separate git wiki adapter pending','attachments':'metadata/link only; binary extraction pending'},'historical_file_revisions':'not captured; default-branch tip only','reuse_permissions':permission}
        return rows,coverage

def capture(config,out,initial=False):
    gh=GitHub(); cfg=json.loads(Path(config).read_text());out=Path(out);out.mkdir(parents=True,exist_ok=True)
    records=[];coverage=[]
    names=[cfg['organization']+'/'+n for n in (cfg['initial'] if initial else cfg['repositories'])]
    discovery=[]
    try: discovery=[r['full_name'] for r in gh.pages('https://api.github.com/orgs/'+cfg['organization']+'/repos?per_page=100&type=public')]
    except Exception as e: coverage.append({'source':'discovery','state':'failed','error':str(e)})
    for name in names+([] if initial else cfg['external_repositories']):
        try:
            rows,c=gh.repo(name);records.extend(rows);coverage.append(c)
        except Exception as e: coverage.append({'repository':name,'state':'failed','captured_at':None,'error':str(e),'retained_data':False})
    manifest={'coverage':coverage,'discovered_not_admitted':sorted(set(discovery)-set(names)),'records':len(records),'capture_time':now()}
    (out/'records.json').write_text(json.dumps(records,indent=2));(out/'coverage.json').write_text(json.dumps(manifest,indent=2))
    return records,manifest

import os,time
from contextlib import asynccontextmanager
from collections import defaultdict,deque
from fastapi import FastAPI,Request,HTTPException
from fastapi.middleware.cors import CORSMiddleware
from mcp.server import MCPServer
from mcp.types import ToolAnnotations
from .store import Store
from .embeddings import Embeddings

def create_app(store):
    mcp=MCPServer('WeBuild read-only retrieval',version='0.1.0')
    annotation=ToolAnnotations(readOnlyHint=True,destructiveHint=False,idempotentHint=True,openWorldHint=False)
    @mcp.tool(annotations=annotation)
    def search(q:str,snapshot:str|None=None,status:str|None=None,version:str|None=None,scope:str|None=None,offset:int=0,limit:int=20)->dict:
        return store.search(q,snapshot,status,version,scope,offset,limit)
    @mcp.tool(annotations=annotation)
    def get_source(id:str,snapshot:str|None=None)->dict:return store.source(id,snapshot)
    @mcp.tool(annotations=annotation)
    def get_related_sources(id:str|None=None,topic:str|None=None,snapshot:str|None=None)->dict:return store.related(id,topic,snapshot)
    @mcp.tool(annotations=annotation)
    def get_related_specs(id:str,snapshot:str|None=None)->dict:return store.related(id,None,snapshot,True)
    @mcp.tool(annotations=annotation)
    def get_decision_history(id:str)->dict:return store.history(id)
    @mcp.tool(annotations=annotation)
    def get_changes(before:str,after:str|None=None)->dict:return store.changes(before,after)
    transport=mcp.streamable_http_app(stateless_http=True,json_response=True,host=os.getenv('SERVICE_HOST','127.0.0.1'))
    @asynccontextmanager
    async def lifespan(app):
        async with transport.router.lifespan_context(transport):yield
    app=FastAPI(title='WeBuild retrieval',lifespan=lifespan)
    origins=os.getenv('ALLOWED_ORIGINS','http://localhost:8080').split(',')
    app.add_middleware(CORSMiddleware,allow_origins=origins,allow_methods=['GET'],allow_headers=['Content-Type'])
    buckets=defaultdict(deque)
    @app.middleware('http')
    async def limits(request:Request,call_next):
        from starlette.responses import JSONResponse
        origin=request.headers.get('origin')
        if origin and origin not in origins:return JSONResponse({'detail':'Origin not allowed'},403)
        if request.url.path.startswith('/v1/') and request.method not in ['GET','OPTIONS']:return JSONResponse({'detail':'Read only'},405)
        key=request.client.host; bucket=buckets[key]; t=time.monotonic()
        while bucket and bucket[0]<t-60:bucket.popleft()
        if len(bucket)>=120:return JSONResponse({'detail':'Rate limit'},429)
        bucket.append(t)
        response=await call_next(request);response.headers['X-Content-Type-Options']='nosniff';return response
    @app.exception_handler(LookupError)
    async def missing(request,e):
        from starlette.responses import JSONResponse
        return JSONResponse({'detail':str(e)},404)
    @app.exception_handler(ValueError)
    async def invalid(request,e):
        from starlette.responses import JSONResponse
        return JSONResponse({'detail':str(e)},400)
    app.get('/v1/search')(search)
    app.get('/v1/sources/{id:path}')(get_source)
    app.get('/v1/relations')(get_related_sources)
    app.get('/v1/decisions/{id:path}/history')(get_decision_history)
    app.get('/v1/changes')(get_changes)
    @app.get('/v1/manifest')
    def manifest(snapshot:str|None=None):return store.manifest(snapshot)
    @app.get('/health')
    def health():
        from datetime import datetime,timezone
        m=store.manifest();age=(datetime.now(timezone.utc)-datetime.fromisoformat(m['published_at'])).total_seconds()
        if age>36*3600:raise HTTPException(503,'Publication older than 36 hours')
        return {'snapshot':m['snapshot'],'age_seconds':age,'failed_sources':[s for s in m['coverage'].get('coverage',[]) if s['state']=='failed']}
    app.mount('/',transport)
    return app

def factory():return create_app(Store(os.environ['RETRIEVAL_DATABASE_URL'],Embeddings()))

import argparse,json,os
